command:
set -eu
printf 'boot_id='; cat /proc/sys/kernel/random/boot_id
printf 'service_active='; systemctl is-active mariadb
printf 'service_enabled='; systemctl is-enabled mariadb
stat -c 'env_owner=%U env_group=%G env_mode=%a' /etc/inventory-db.env
printf 'env_keys='; cut -d= -f1 /etc/inventory-db.env | paste -sd, -
env_mode="$(stat -c '%a' /etc/inventory-db.env)"
[ "$env_mode" = 600 ]
. /etc/inventory-db.env
printf 'application_ping='; MYSQL_PWD="$DB_PASSWORD" mysqladmin --protocol=socket -h "$DB_HOST" -u "$DB_USER" ping
MYSQL_PWD="$DB_PASSWORD" mysql --protocol=socket -h "$DB_HOST" -u "$DB_USER" "$DB_NAME" <<'ANTRIEB_SQL'
INSERT INTO items (name, quantity) VALUES ('restart-persistence-check', 1)
  ON DUPLICATE KEY UPDATE quantity=VALUES(quantity);
SELECT DATABASE() AS database_name, CURRENT_USER() AS authenticated_account;
SHOW TABLES;
DESCRIBE items;
SELECT id, name, quantity FROM items WHERE name='restart-persistence-check';
SHOW GRANTS;
ANTRIEB_SQL
unset DB_PASSWORD MYSQL_PWD

